function validate([nums1, nums2, queries]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2) || nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 10^5 values.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1e9;
  if (!nums1.every(ok) || !nums2.every(ok)) return 'Every value is an integer from 1 to 10^9.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  if (!queries.every(q => Array.isArray(q) && q.length === 2 && ok(q[0]) && ok(q[1]))) return 'Each query is [x, y] with integers from 1 to 10^9.';
  return null;
}

