function maximumSumQueries(nums1, nums2, queries) {
  const pairs = nums1.map((a, i) => [a, nums2[i]]);
  pairs.sort((p, q) => q[0] - p[0]);
  const order = queries.map((_, i) => i);
  order.sort((i, j) => queries[j][0] - queries[i][0]);
  const answer = new Array(queries.length).fill(-1);
  const stack = [];
  let next = 0;

  for (const qi of order) {
    const [x, y] = queries[qi];
    while (next < pairs.length && pairs[next][0] >= x) {
      const [a, b] = pairs[next];
      const sum = a + b;
      next++;
      while (stack.length > 0 && stack[stack.length - 1][1] <= sum) {
        stack.pop();
      }
      if (stack.length === 0 || stack[stack.length - 1][0] < b) {
        stack.push([b, sum]);
      }
    }
    let low = 0;
    let high = stack.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (stack[mid][0] >= y) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    if (low < stack.length) {
      answer[qi] = stack[low][1];
    }
  }
  return answer;
}

