function maximumSumQueries(nums1, nums2, queries) {
  return queries.map(([x, y]) => {
    let most = -1;
    for (let j = 0; j < nums1.length; j++) {
      if (nums1[j] >= x && nums2[j] >= y) most = Math.max(most, nums1[j] + nums2[j]);
    }
    return most;
  });
}

