function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const m = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  // A small value range makes ties and dominated pairs common; a huge one tests the limits.
  const scales = large ? [1000, 1000000, 1000000000] : [5, 10, 1000000000];
  const top = scales[Math.floor(rand() * scales.length)];
  const value = () => 1 + Math.floor(rand() * top);
  const nums1 = Array.from({ length: n }, value);
  // Sometimes make nums2 fall as nums1 rises, so no single pair wins every query.
  const traded = rand() < 0.4;
  const nums2 = nums1.map(a => (traded ? Math.max(1, Math.min(top, top + 1 - a + Math.floor(rand() * 3) - 1)) : value()));
  const queries = Array.from({ length: m }, () => [value(), value()]);
  return [nums1, nums2, queries];
}
